(() => {
'use strict';
const config = window.LIKE_CONFIG || {};
const connected = Boolean(config.supabaseUrl && config.supabaseKey);
let session;
try { session = JSON.parse(sessionStorage.getItem('like-session') || 'null'); } catch { sessionStorage.removeItem('like-session'); }
let renewing;
const user = () => session?.user;
function clearSession() {session=null;sessionStorage.removeItem('like-session');}
async function request(path, options = {}, auth = true) {
  if(auth && session && session.expires_at < Date.now()/1000+60) {
    if(!renewing) renewing=request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})},false).then(saveSession).catch(error=>{clearSession();throw error;}).finally(()=>{renewing=null;});
    await renewing;
  }
  const response = await fetch(config.supabaseUrl.replace(/\/$/,'')+path,{...options,headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(auth ? {Authorization:`Bearer ${session?.access_token || config.supabaseKey}`} : {}),...options.headers}});
  const text = await response.text(); let body; try {body=text ? JSON.parse(text) : null;} catch {throw Error('Resposta inválida do servidor.');}
  if(!response.ok) {
    if(auth && response.status===401) {clearSession();throw Error('Sua sessão expirou. Entre novamente.');}
    throw Error(body?.code==='23505' ? 'Este aluno já está agendado nesse horário.' : body?.message || body?.error_description || 'Não foi possível concluir. Tente novamente.');
  }
  return body;
}
function saveSession(value) {session={...value,expires_at:Date.now()/1000+value.expires_in};sessionStorage.setItem('like-session',JSON.stringify(session));}
async function login(email,password) {
  saveSession(await request('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})},false));
  try {
    await checkStaff();
  } catch(error) {clearSession();throw error;}
}
async function checkStaff() {
  if(!session?.user?.id) throw Error('Entre novamente para acessar a agenda.');
  const staff=await request('/rest/v1/staff?select=*&user_id=eq.'+encodeURIComponent(session.user.id));
  if(!staff.length) {clearSession();throw Error('Funcionário não autorizado. Solicite acesso ao responsável pelo estúdio.');}
  session.user.staff=staff[0];sessionStorage.setItem('like-session',JSON.stringify(session));
}
async function logout() {try {if(connected&&session) await request('/auth/v1/logout',{method:'POST'});} finally {clearSession();}}
const demoKey='like-demo-v1';
function local() {return JSON.parse(localStorage.getItem(demoKey)||'{"teachers":[],"appointments":[]}');}
async function readAll(table,order) {
  const rows=[];let offset=0;
  for(;;) {const batch=await request(`/rest/v1/${table}?select=*&order=${order}&limit=500&offset=${offset}`);rows.push(...batch);if(batch.length<500)return rows;offset+=500;}
}
async function load() {if(!connected) return local();await checkStaff();const [teachers,appointments]=await Promise.all([readAll('teachers','name,id'),readAll('appointments','starts_at,id')]);return {teachers,appointments};}
async function save(table,record,id) {
  if(connected) return request(`/rest/v1/${table}${id?'?id=eq.'+encodeURIComponent(id):''}`,{method:id?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(record)});
  const data=local();if(id) data[table]=data[table].map(row=>row.id===id?{...row,...record}:row);else data[table].push({...record,id:crypto.randomUUID()});localStorage.setItem(demoKey,JSON.stringify(data));
}
async function remove(table,id) {if(connected) return request(`/rest/v1/${table}?id=eq.${encodeURIComponent(id)}`,{method:'DELETE'});const data=local();data[table]=data[table].filter(row=>row.id!==id);localStorage.setItem(demoKey,JSON.stringify(data));}

// Calendar arithmetic uses Brasília dates, independently of the device timezone.
function weeklyRecords(record, until) {
  const first=new Date(record.starts_at), end=new Date(until+'T23:59:59-03:00');
  if(!Number.isFinite(end.getTime()) || end<first) throw Error('Escolha uma data final igual ou posterior à primeira aula.');
  const count=Math.floor((end-first)/(7*86400000))+1;
  if(count>104) throw Error('Programe no máximo 104 aulas por sequência.');
  const series_id=crypto.randomUUID();
  return Array.from({length:count},(_,i)=>({...record,id:crypto.randomUUID(),series_id,starts_at:new Date(first.getTime()+i*7*86400000).toISOString()}));
}
function sequenceChanges(rows, original, record) {
  const delta=new Date(record.starts_at)-new Date(original.starts_at);
  return rows.filter(row=>row.series_id===original.series_id).map(row=>({...record,id:row.id,series_id:original.series_id,starts_at:new Date(new Date(row.starts_at).getTime()+delta).toISOString()}));
}
async function saveAppointments(records, editing=false) {
  if(connected) return request('/rest/v1/rpc/save_appointment_sequence',{method:'POST',body:JSON.stringify({records,editing})});
  const data=local(), ids=new Set(records.map(r=>r.id));
  if(editing && records.some(r=>!data.appointments.some(a=>a.id===r.id))) throw Error('A agenda mudou. Atualize e tente novamente.');
  const next=[...data.appointments.filter(r=>!editing||!ids.has(r.id)),...records];
  const keys=new Set();
  for(const row of next){const key=row.student.trim().toLocaleLowerCase()+'|'+new Date(row.starts_at).toISOString();if(keys.has(key))throw Error('Este aluno já está agendado nesse horário. Nenhuma aula foi salva.');keys.add(key);}
  data.appointments=next;localStorage.setItem(demoKey,JSON.stringify(data));
}
async function removeSequence(seriesId) {
  if(connected) return request('/rest/v1/appointments?series_id=eq.'+encodeURIComponent(seriesId),{method:'DELETE'});
  const data=local();data.appointments=data.appointments.filter(a=>a.series_id!==seriesId);localStorage.setItem(demoKey,JSON.stringify(data));
}

const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const studioDate=d=>new Date(new Date(d).toLocaleString('en-US',{timeZone:'America/Sao_Paulo'}));
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const time=d=>new Date(d).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'});
const format=(d,options)=>d.toLocaleDateString('pt-BR',options);
let data={teachers:[],appointments:[]}, selected=dateKey(studioDate(new Date())), view='week', page='agenda', filter='', query='';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function dialog(html){modal.innerHTML=html;modal.showModal();modal.querySelector('[data-close]')?.addEventListener('click',()=>modal.close());}
modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
async function refresh(){try {data=await load();render();}catch(e){if(connected&&!user()){data={teachers:[],appointments:[]};loginPage();}toast(e.message);}}
function loginPage(){app.innerHTML=`<main class="login"><div class="login-art"><div class="brand-wordmark" aria-label="LIKE Studio Pilates"><span class="brand-name">LIKE</span><span class="brand-subtitle">Studio Pilates</span></div><div><p class="eyebrow">LIKE STUDIO PILATES</p><h1>Seu corpo é<br><i>seu maior bem!</i></h1></div><p>O espaço da equipe LIKE Pilates.</p></div><section class="login-form"><p class="eyebrow">ÁREA INTERNA</p><h2>Bem-vindo de volta.</h2><p>Acesse a agenda e prepare o próximo encontro.</p><form id="login"><label>E-mail<input type="email" name="email" autocomplete="username" required></label><label>Senha<input type="password" name="password" autocomplete="current-password" required></label><p id="login-error" role="alert"></p><button class="primary">Entrar na agenda →</button></form><small>Acesso exclusivo para funcionários autorizados.</small></section></main>`;$('#login').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await login(e.target.email.value,e.target.password.value);await refresh();}catch(err){$('#login-error').textContent=err.message.includes('Funcionário não autorizado')?err.message:'Não foi possível entrar. Verifique o e-mail, a senha e sua conexão.';}finally{b.disabled=false;}};}
function days(){const start=new Date(selected+'T12:00:00');if(view==='week')start.setDate(start.getDate()-((start.getDay()+6)%7));return Array.from({length:view==='week'?7:1},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d;});}
function filtered(){return data.appointments.filter(a=>(!filter||a.teacher_id===filter)&&a.student.toLocaleLowerCase().includes(query.toLocaleLowerCase()));}
function render(){if(connected&&!user())return loginPage();const ds=days(), today=dateKey(studioDate(new Date())), dayRows=data.appointments.filter(a=>dateKey(studioDate(a.starts_at))===selected);app.innerHTML=`<aside class="sidebar"><div class="brand-wordmark" aria-label="LIKE Studio Pilates"><span class="brand-name">LIKE</span><span class="brand-subtitle">Studio Pilates</span></div><p class="nav-label">ESTÚDIO · ÁREA INTERNA</p><nav><button data-page="agenda" class="${page==='agenda'?'active':''}"><span>▦</span> Agenda <b>→</b></button><button data-page="teachers" class="${page==='teachers'?'active':''}"><span>♧</span> Professores <b>${data.teachers.length}</b></button></nav><div class="sidebar-note"><span>✳</span><h3>Seu corpo é<br>seu maior bem!</h3><p>Uma boa aula começa<br>com cuidado nos detalhes.</p></div><div class="account"><div class="avatar">LK</div><div><strong>${esc(user()?.staff?.name||'Equipe LIKE')}</strong><small>${connected?esc(user()?.staff?.job_title||'Acesso autorizado'):'Demonstração local'}</small></div><button id="logout" aria-label="Sair">↗</button></div></aside><main class="workspace"><header><span>Estúdio <span class="muted">/</span> ${page==='agenda'?'Agenda':'Professores'}</span><span class="connection"><i></i>${connected?'Supabase conectado':'Modo demonstração'}</span></header><section class="content">${!connected?'<div class="demo-banner">Prévia local · Os dados ficam apenas neste navegador. Configure o Supabase antes de usar com alunos reais.</div>':''}<div class="page-heading"><div><p class="eyebrow">${page==='agenda'?'CADA MOVIMENTO, UM NOVO ENCONTRO':'QUEM FAZ O ESTÚDIO ACONTECER'}</p><h1>${page==='agenda'?'Agenda do estúdio':'Nossos professores'}<span>.</span></h1><p>${page==='agenda'?'Organize as aulas. Cuide de cada aluno.':'Gerencie os profissionais que acompanham cada movimento.'}</p></div><button id="create" class="primary">＋ ${page==='agenda'?'Agendar aula':'Cadastrar professor'}</button></div>${page==='agenda'?`<div class="stats"><div><span>Aulas no dia selecionado</span><strong>${dayRows.length.toString().padStart(2,'0')}<small>agendamentos</small></strong></div><div><span>Alunos no dia</span><strong>${new Set(dayRows.map(a=>a.student.toLowerCase())).size.toString().padStart(2,'0')}<small>para receber</small></strong></div><div><span>Professores cadastrados</span><strong>${data.teachers.filter(t=>t.active).length.toString().padStart(2,'0')}<small>ativos no estúdio</small></strong></div><div class="quote"><span>✳</span><p>Seu corpo é<br><em>seu maior bem!</em></p></div></div><section class="agenda"><div class="toolbar"><div class="date-navigation"><button id="prev" aria-label="Período anterior">‹</button><button id="next" aria-label="Próximo período">›</button><h2>${format(ds[0],{month:'long',year:'numeric'})}</h2><button id="today">Hoje</button><input id="date" type="date" aria-label="Ir para data" value="${selected}"></div><div class="segmented"><button data-view="day" class="${view==='day'?'active':''}">Dia</button><button data-view="week" class="${view==='week'?'active':''}">Semana</button></div></div><div class="filters"><span>⌕ <input id="search" type="search" placeholder="Buscar aluno…" value="${esc(query)}" aria-label="Buscar aluno"></span><select id="teacher-filter" aria-label="Filtrar por professor"><option value="">Todos os professores</option>${data.teachers.map(t=>`<option value="${t.id}" ${filter===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button id="refresh">↻ Atualizar</button></div><div class="calendar-scroll"><div class="calendar ${view}"><div class="calendar-heading"><div class="time-label">HORÁRIO</div>${ds.map(d=>`<div class="day-heading ${dateKey(d)===today?'today':''}"><span>${format(d,{weekday:'short'}).replace('.','')}</span><strong>${d.getDate()}</strong></div>`).join('')}</div><div class="calendar-body"><div class="hours">${Array.from({length:17},(_,i)=>`<div>${String(i+6).padStart(2,'0')}:00</div>`).join('')}</div>${ds.map(d=>`<div class="day-column" data-date="${dateKey(d)}">${Array.from({length:17},(_,i)=>`<button class="slot" data-day="${dateKey(d)}" data-hour="${i+6}" aria-label="Agendar ${dateKey(d)} às ${i+6} horas"></button>`).join('')}${cards(d)}</div>`).join('')}</div></div></div><footer class="agenda-footer"><span><i></i> Clique em uma aula para ver os detalhes</span><span>Horário de Brasília</span></footer></section>`:teacherPage()}<footer class="page-footer">LIKE PILATES <span>Seu corpo é seu maior bem!</span></footer></section></main>`;
$('#logout').onclick=async()=>{try{await logout();}catch{toast('Sessão local encerrada.');}finally{data={teachers:[],appointments:[]};if(connected)loginPage();else toast('Você está na demonstração local.');}};$('#create').onclick=()=>page==='agenda'?appointmentForm():teacherForm();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});if(page==='agenda')bindAgenda();else document.querySelectorAll('[data-teacher]').forEach(b=>b.onclick=()=>teacherForm(data.teachers.find(t=>t.id===b.dataset.teacher)));}
function cards(d){
  const rows=filtered().filter(a=>dateKey(studioDate(a.starts_at))===dateKey(d)).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
  const groups=[];let group=[],groupEnd=0;
  for(const a of rows){const begin=new Date(a.starts_at).getTime();if(group.length&&begin>=groupEnd){groups.push(group);group=[];groupEnd=0;}group.push(a);groupEnd=Math.max(groupEnd,begin+a.duration*60000);}if(group.length)groups.push(group);
  const positions=new Map();
  for(const members of groups){const ends=[];for(const a of members){const begin=new Date(a.starts_at).getTime();let lane=ends.findIndex(end=>end<=begin);if(lane<0)lane=ends.length;ends[lane]=begin+a.duration*60000;positions.set(a.id,{lane});}for(const a of members)positions.get(a.id).count=ends.length;}
  return rows.map(a=>{const start=studioDate(a.starts_at),teacher=data.teachers.find(t=>t.id===a.teacher_id),position=positions.get(a.id);
  return '<button class="class-card tone-'+Math.max(0,data.teachers.findIndex(t=>t.id===a.teacher_id))%4+'" data-appointment="'+a.id+'" style="top:'+((start.getHours()-6)*88+start.getMinutes()/60*88)+'px;height:'+Math.max(34,a.duration/60*88-4)+'px;left:calc('+position.lane/position.count*100+'% + 5px);width:calc('+100/position.count+'% - 10px)"><span>'+time(a.starts_at)+' · '+a.duration+' min</span><strong>'+esc(a.student)+'</strong><small>'+esc(teacher?.name||'Professor')+(a.series_id?' · ↻':'')+(a.notes?' · ≡':'')+'</small></button>';
  }).join('');
}
function bindAgenda(){for(const [id,step] of [['prev',-1],['next',1]])$('#'+id).onclick=()=>{const d=new Date(selected+'T12:00:00');d.setDate(d.getDate()+step*(view==='week'?7:1));selected=dateKey(d);render();};$('#today').onclick=()=>{selected=dateKey(studioDate(new Date()));render();};$('#date').onchange=e=>{if(e.target.value){selected=e.target.value;render();}};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#teacher-filter').onchange=e=>{filter=e.target.value;render();};$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();try{$('#search').setSelectionRange(pos,pos);}catch{}};$('#refresh').onclick=refresh;document.querySelectorAll('[data-appointment]').forEach(b=>b.onclick=()=>appointmentForm(data.appointments.find(a=>a.id===b.dataset.appointment)));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>appointmentForm(null,b.dataset.day,String(b.dataset.hour).padStart(2,'0')+':00'));}
function teacherPage(){return `<div class="teacher-grid">${data.teachers.length?data.teachers.map((t,i)=>`<button class="teacher-card" data-teacher="${t.id}"><span class="teacher-avatar tone-${i%4}">${esc(t.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><span><strong>${esc(t.name)}</strong><small>${esc(t.specialty||'Pilates')} · ${t.active?'Ativo':'Inativo'}</small></span><span>↗</span></button>`).join(''):'<div class="empty"><span>♧</span><h2>Vamos conhecer a equipe?</h2><p>Cadastre o primeiro professor para começar a agendar aulas.</p></div>'}</div>`;}
function appointmentForm(a=null,date=selected,hour='08:00'){const active=data.teachers.filter(t=>t.active||t.id===a?.teacher_id);if(!active.length){toast('Cadastre um professor antes de agendar a primeira aula.');page='teachers';render();teacherForm();return;}const dt=a?studioDate(a.starts_at):null;dialog(`<form id="appointment-form"><div class="modal-heading"><div><p class="eyebrow">AGENDA LIKE</p><h2>${a?'Detalhes da aula':'Um novo encontro'}</h2></div><button type="button" data-close aria-label="Fechar">✕</button></div><label>Nome do aluno<input name="student" maxlength="120" required placeholder="Como o aluno se chama?" value="${esc(a?.student||'')}"></label><label>Professor<select name="teacher_id" required>${active.map(t=>`<option value="${t.id}" ${a?.teacher_id===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><div class="form-row"><label>Data<input type="date" name="date" required value="${dt?dateKey(dt):date}"></label><label>Início<input type="time" name="time" min="06:00" max="22:30" required value="${dt?String(dt.getHours()).padStart(2,'0')+':'+String(dt.getMinutes()).padStart(2,'0'):hour}"></label><label>Duração<select name="duration">${[30,45,50,60,90,120].map(n=>`<option value="${n}" ${(a?.duration||60)===n?'selected':''}>${n} min</option>`).join('')}</select></label></div>${!a?`<fieldset class="recurrence"><legend>Programar aluno</legend><label>Repetição<select name="repeat"><option value="none">Não repetir</option><option value="weekly">Toda semana, no mesmo dia e horário</option></select></label><label id="repeat-end" hidden>Repetir até<input type="date" name="until" value="${date}" min="${date}"></label><small id="repeat-summary" aria-live="polite">Escolha a repetição para reservar as próximas aulas.</small></fieldset>`:a.series_id?`<p class="series-info">↻ Aula de uma sequência com ${data.appointments.filter(row=>row.series_id===a.series_id).length} aulas. Ao salvar, escolha quais aulas alterar.</p>`:''}<label>Observações do aluno <span class="muted">· opcional</span><textarea name="notes" maxlength="3000" rows="4" placeholder="Cuidados, adaptações ou informações para esta aula…">${esc(a?.notes||'')}</textarea></label><small>As observações ficam disponíveis apenas para a equipe autorizada.</small><p class="form-error" role="alert"></p><div class="modal-actions">${a?'<button type="button" class="danger" id="delete">Excluir aula</button>':'<button type="button" id="cancel">Cancelar</button>'}<button class="primary" type="submit">${a?'Salvar alterações':'Confirmar agendamento'} →</button></div></form>`);$('#cancel')?.addEventListener('click',()=>modal.close());$('#delete')?.addEventListener('click',()=>deleteAppointment(a));if(!a){const form=$('#appointment-form');const preview=()=>{const repeating=form.elements.repeat.value==='weekly';$('#repeat-end').hidden=!repeating;form.elements.until.required=repeating;form.elements.until.min=form.elements.date.value;try{const count=weeklyRecords({starts_at:new Date(form.elements.date.value+'T'+form.elements.time.value+':00-03:00').toISOString()},form.elements.until.value).length;$('#repeat-summary').textContent=repeating?`${count} aula(s), toda semana, até ${format(new Date(form.elements.until.value+'T12:00:00'),{day:'2-digit',month:'2-digit',year:'numeric'})}. Máximo: 104 aulas.`:'Escolha a repetição para reservar as próximas aulas.';}catch(error){$('#repeat-summary').textContent=repeating?error.message:'';}};for(const name of ['repeat','until','date','time'])form.elements[name].addEventListener('change',preview);}$('#appointment-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const start=new Date(f.get('date')+'T'+f.get('time')+':00-03:00');const duration=Number(f.get('duration'));if(Number(f.get('time').slice(0,2))*60+Number(f.get('time').slice(3))+duration>23*60){$('.form-error').textContent='A aula deve terminar até 23h.';return;}const record={student:f.get('student').trim(),teacher_id:f.get('teacher_id'),starts_at:start.toISOString(),duration,notes:f.get('notes').trim()};if(!record.student){$('.form-error').textContent='Informe o nome do aluno.';return;}if(a?.series_id){chooseSequence(a,record);return;}if(!a&&f.get('repeat')==='weekly'){try{const records=weeklyRecords(record,f.get('until'));await mutate(e.submitter,()=>saveAppointments(records),`${records.length} aulas programadas na agenda.`);}catch(error){$('.form-error').textContent=error.message;}return;}await mutate(e.submitter,()=>save('appointments',record,a?.id),'Aula salva na agenda.');};}
function chooseSequence(a,record){const rows=sequenceChanges(data.appointments,a,record);dialog(`<div class="modal-heading"><h2>Alterar quais aulas?</h2><button data-close aria-label="Fechar">✕</button></div><p>Escolha se as alterações de <strong>${esc(record.student)}</strong> valem apenas para esta aula ou para todas as ${rows.length} aulas da sequência, incluindo as anteriores.</p><p>Ao alterar a data, todas as aulas serão deslocadas pelo mesmo número de dias, mantendo o intervalo semanal.</p><p class="form-error" role="alert"></p><div class="modal-actions"><button id="only-one">Só esta aula</button><button class="primary" id="whole-series">Toda a sequência</button></div>`);const lock=async(button,operation,message)=>{const buttons=[...modal.querySelectorAll('.modal-actions button')];buttons.forEach(b=>b.disabled=true);await mutate(button,operation,message);buttons.forEach(b=>b.disabled=false);};$('#only-one').onclick=e=>lock(e.target,()=>save('appointments',record,a.id),'Aula alterada.');$('#whole-series').onclick=e=>lock(e.target,()=>saveAppointments(rows,true),'Sequência alterada.');}
async function mutate(button,operation,message){button.disabled=true;try{await operation();modal.close();await refresh();toast(message);}catch(e){$('.form-error').textContent=e.message;}finally{button.disabled=false;}}
function deleteAppointment(a){dialog(`<div class="modal-heading"><h2>Excluir esta aula?</h2><button data-close aria-label="Fechar">✕</button></div><p>O agendamento de <strong>${esc(a.student)}</strong>, às ${time(a.starts_at)}, será removido.</p>${a.series_id?`<label>Excluir<select id="delete-scope"><option value="one">Somente esta aula</option><option value="all">Toda a sequência (${data.appointments.filter(row=>row.series_id===a.series_id).length} aulas, incluindo anteriores)</option></select></label>`:''}<p class="form-error" role="alert"></p><div class="modal-actions"><button id="back">Voltar</button><button class="danger" id="confirm-delete">Excluir aula</button></div>`);$('#back').onclick=()=>appointmentForm(a);$('#confirm-delete').onclick=e=>mutate(e.target,()=>$('#delete-scope')?.value==='all'?removeSequence(a.series_id):remove('appointments',a.id),'Agendamento excluído.');}
function teacherForm(t=null){dialog(`<form id="teacher-form"><div class="modal-heading"><div><p class="eyebrow">EQUIPE LIKE</p><h2>${t?'Editar professor':'Novo professor'}</h2></div><button type="button" data-close aria-label="Fechar">✕</button></div><label>Nome completo<input name="name" maxlength="120" required value="${esc(t?.name||'')}" placeholder="Nome do profissional"></label><label>Especialidade<input name="specialty" maxlength="120" value="${esc(t?.specialty||'')}" placeholder="Ex.: Pilates clínico"></label><label>Status<select name="active"><option value="true">Ativo</option><option value="false" ${t&&!t.active?'selected':''}>Inativo</option></select></label><small>Professores inativos mantêm o histórico das aulas.</small><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" id="cancel">Cancelar</button><button class="primary">Salvar professor →</button></div></form>`);$('#cancel').onclick=()=>modal.close();$('#teacher-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim())return;mutate(e.submitter,()=>save('teachers',{name:f.get('name').trim(),specialty:f.get('specialty').trim(),active:f.get('active')==='true'},t?.id),'Professor salvo.');};}
render();if(!connected||user())refresh();

})();
